  "faq": [
    {
      "q": "AIBAN என்ன செய்கிறது?",
      "a": "நீங்கள் ஏற்கனவே வெளியிடும் உள்ளடக்கத்தை AIBAN படிக்கிறது, உதாரணமாக உங்கள் இணையதளம், உங்கள் வலைப்பதிவு அல்லது நீங்கள் தேர்ந்தெடுக்கும் செய்தித் தளங்கள். அது உங்கள் பாணியில் புதிய இதழ்களை எழுதி செய்திமடலாக அனுப்புகிறது. ஒவ்வொரு சந்தாதாரரும் தாம் தேர்ந்தெடுத்த மொழியில் அதைப் பெறுகிறார், அனுப்புநராக உங்கள் பெயர் இருக்கும்."
    },
    {
      "q": "இலவசத் திட்டம் உள்ளதா?",
      "a": "ஆம். இலவசத் திட்டத்தில் 1 மூலமும் 100 சந்தாதாரர்கள் வரையும் அடங்கும். மேலும் தேவைப்பட்டால் எங்களுக்கு எழுதுங்கள், உங்கள் திட்டத்தை மாற்றுவோம்."
    },
    {
      "q": "சந்தாதாரர்கள் தங்கள் மொழியில் newsletter-ஐ எப்படிப் பெறுவார்கள்?",
      "a": "பதிவு செய்யும்போது ஒவ்வொரு சந்தாதாரரும் விருப்ப மொழியைத் தேர்ந்தெடுக்கிறார். அனுப்பும் முன் AIBAN ஒவ்வொரு இதழையும் அந்த மொழியில் மொழிபெயர்க்கிறது."
    },
    {
      "q": "இதழ்கள் என் சொந்த மின்னஞ்சல் முகவரியிலிருந்து வர முடியுமா?",
      "a": "இதழ்கள் AIBAN-இன் அனுப்பும் முகவரியிலிருந்து உங்கள் பெயருடனும் மின்னஞ்சல் கையொப்பத்துடனும் செல்கின்றன, பதில்கள் உங்கள் இன்பாக்ஸுக்கு வருகின்றன. நாங்கள் உங்கள் மின்னஞ்சல் கடவுச்சொல்லைக் கேட்பதில்லை, எனவே உங்களுடைய எதுவும் கசிய வாய்ப்பில்லை."
    },
    {
      "q": "மக்கள் எப்படிச் சந்தா செலுத்துவார்கள்?",
      "a": "உங்களுக்கு ஒரு பதிவுப் பக்கமும், உங்கள் இணையதளத்தில் வைக்கக்கூடிய பதிவு விட்ஜெட்டும் கிடைக்கும். நீங்களே நபர்களைச் சேர்க்கலாம் அல்லது ஒரு பட்டியலைப் பதிவேற்றலாம்."
    },
    {
      "q": "எப்போது வேண்டுமானாலும் ரத்து செய்யலாமா?",
      "a": "ஆம். எப்போது வேண்டுமானாலும் info@aiban.news-க்கு எழுதுங்கள், உங்கள் கட்டணத் திட்டத்தை ரத்து செய்வோம் அல்லது உங்களை இலவசத் திட்டத்துக்கு மாற்றுவோம்."
    }
  ],
